import{_ as n,o as a,c as t,ah as r}from"./chunks/framework.BsNNkeaH.js";const d=JSON.parse('{"title":"Paiements en ligne","description":"","frontmatter":{"layout":"doc"},"headers":[],"relativePath":"guide/parent/paiements-en-ligne.md","filePath":"src/guide/parent/paiements-en-ligne.md"}'),s={name:"guide/parent/paiements-en-ligne.md"};function i(o,e,l,u,c,p){return a(),t("div",null,[...e[0]||(e[0]=[r('<h1 id="paiements-en-ligne" tabindex="-1">Paiements en ligne <a class="header-anchor" href="#paiements-en-ligne" aria-label="Permalink to &quot;Paiements en ligne&quot;">​</a></h1><p>Cette page explique comment suivre les frais de scolarité de votre enfant et régler un paiement directement en ligne, sans vous déplacer.</p><h2 id="suivre-les-frais-de-scolarite" tabindex="-1">Suivre les frais de scolarité <a class="header-anchor" href="#suivre-les-frais-de-scolarite" aria-label="Permalink to &quot;Suivre les frais de scolarité&quot;">​</a></h2><p>Sur la fiche de votre enfant, la section <strong>Paiements</strong> affiche quatre chiffres :</p><ul><li><strong>Total dû</strong> — le montant total des frais pour l&#39;année.</li><li><strong>Remise</strong> — le montant des remises éventuellement accordées.</li><li><strong>Total payé</strong> — ce qui a déjà été réglé, en ligne ou à l&#39;accueil.</li><li><strong>Solde</strong> — ce qu&#39;il reste à payer.</li></ul><p>Si un plan de paiement par tranches a été mis en place, un tableau <strong>Plan de paiement</strong> liste chaque tranche avec son libellé, son montant, sa date d&#39;échéance et son statut (<strong>Payée</strong>, <strong>En retard</strong> ou <strong>À venir</strong>).</p><p>L&#39;historique complet des paiements figure dans un second tableau, avec la date, le montant, la méthode (mobile money, carte bancaire, dépôt bancaire…), l&#39;article de frais concerné et le statut du paiement (<strong>Payé</strong>, <strong>En attente</strong> ou <strong>Échoué</strong>). Cet historique regroupe aussi bien vos paiements en ligne que ceux encaissés directement à l&#39;accueil de l&#39;établissement.</p><h2 id="payer-en-ligne-par-mobile-money" tabindex="-1">Payer en ligne par mobile money <a class="header-anchor" href="#payer-en-ligne-par-mobile-money" aria-label="Permalink to &quot;Payer en ligne par mobile money&quot;">​</a></h2><p>Tant qu&#39;il reste un solde à régler, un bouton <strong>Payer en ligne</strong> apparaît au-dessus des chiffres de paiement. Pour effectuer un paiement :</p><ol><li>Cliquez sur <strong>Payer en ligne</strong>.</li><li>Dans la fenêtre <strong>Payer par mobile money</strong>, choisissez le <strong>Réseau</strong> à utiliser (Mixx by Yass, Flooz ou T-Money, selon ce que propose votre établissement).</li><li>Saisissez le <strong>Numéro de téléphone</strong> qui recevra la demande de paiement.</li><li>Saisissez le <strong>Montant</strong> à payer — il ne peut pas dépasser le solde restant.</li><li>Cliquez sur <strong>Envoyer la demande de paiement</strong>.</li><li>Validez la demande reçue sur votre téléphone via votre opérateur mobile money.</li></ol><p>Le paiement apparaît immédiatement dans l&#39;historique avec le statut <strong>En attente</strong>, puis passe à <strong>Payé</strong> une fois la transaction confirmée. S&#39;il échoue, il apparaît avec le statut <strong>Échoué</strong> et vous pouvez recommencer.</p><h2 id="telecharger-un-recu" tabindex="-1">Télécharger un reçu <a class="header-anchor" href="#telecharger-un-recu" aria-label="Permalink to &quot;Télécharger un reçu&quot;">​</a></h2><p>Une fois un paiement confirmé, un lien <strong>Télécharger le reçu</strong> apparaît en face de celui-ci dans l&#39;historique — cliquez pour obtenir le reçu au format PDF.</p>',13)])])}const m=n(s,[["render",i]]);export{d as __pageData,m as default};
